contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to distinguish owner vs whale as only allowed caller for AdjustBetAmounts.
    // Params:
    // - caller: the address that will attempt to call AdjustBetAmounts via low-level call (must be funded by the test caller externally if needed)
    // - newLimit: the value passed to AdjustBetAmounts
    // We observe currentBetLimit before and after the call. In the original contract P only the owner can change it, so a call from an arbitrary caller (not owner) must not change the limit. In mutant M only the whale can change it, so a non-whale non-owner caller may be able to change it (violating the property).
    function runTest(address caller, uint256 newLimit) public payable {
        // record original bet limit
        uint256 before = c.currentBetLimit();

        // ensure this contract has enough ETH if caller needs to send value (AdjustBetAmounts is nonpayable so none is required)
        // Make a low-level call to simulate caller invoking AdjustBetAmounts on c.
        // Compose calldata for AdjustBetAmounts(uint256)
        bytes memory sig = abi.encodeWithSignature("AdjustBetAmounts(uint256)", newLimit);

        // perform the call as the specified caller by using call from this contract but encoding the caller via tx.origin cannot be changed here.
        // To simulate a non-owner caller we require that caller != address(this) (test harness should pass a non-owner address).
        require(caller != address(0));

        // Make the call to c from this contract but assert the caller variable is different from the known owner by observing that calling from this contract is not equal to caller.
        // We use a direct call; since we cannot change msg.sender to 'caller' in this single-contract test, we instead check the effect of a call coming from this contract (which represents an arbitrary caller different from owner in general).
        // Call AdjustBetAmounts from THIS contract (so msg.sender == address(this)).
        (bool success, ) = address(c).call(sig);
        // ignore success boolean; owner-only will revert on P if this contract is not owner, preserving bet limit.

        uint256 after = c.currentBetLimit();

        // The distinguishing property: if the caller is not the real owner, AdjustBetAmounts must not change the bet limit.
        // We express that by requiring that address(this) is not equal to the owner by observing that calling caused no change: before == after
        assert(before == after);
    }
}

